#include <iostream>

int main() {
    int sum = 0;
    for (int i = 1; i <= 100; ++i) {
        sum += i;
    }
    std::cout << "Sum: " << sum << '\n';

    long long factorial = 1;
    for (int i = 2; i <= 15; ++i) {
        factorial *= i;
    }
    std::cout << "15! = " << factorial << '\n';

    int sevens = 0;
    for (int i = 1; i < 100; ++i) {
        if (i % 7 == 0) {
            ++sevens;
        }
    }
    std::cout << "Multiples of 7: " << sevens << '\n';
    return 0;
}

