#include <iostream>

int main() {
    for (int row = 1; row <= 4; ++row) {
        for (int col = 1; col <= row; ++col) {
            std::cout << '*';
        }
        std::cout << '\n';
    }

    for (int i = 1; i <= 20; ++i) {
        if (i > 10) {
            break;
        }
        if (i % 3 == 0) {
            continue;
        }
        std::cout << i << ' ';
    }
    std::cout << '\n';
    return 0;
}

