#include <iostream>

int main() {
    for (int row = 1; row <= 3; ++row) {
        for (int col = 1; col <= 4; ++col) {
            std::cout << row * col << ' ';
        }
        std::cout << '\n';
    }

    for (int i = 1; i <= 30; ++i) {
        if (i > 11) {
            break;
        }
        if (i % 2 == 0) {
            continue;
        }
        std::cout << i << ' ';
    }
    std::cout << '\n';
    return 0;
}
